class Algo {
public static int binary_search(int[] a, int n, int x) {
    if (a == null || n <= 0) return -1;
    int low = 0, high = Math.min(n, a.length) - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        int val = a[mid];
        if (val == x) return mid;
        if (val < x) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}
}

class Algo {
public static int binary_search(final int[] a, int n, int x) {
    if (a == null || n <= 0) return -1;
    int lo = 0;
    int hi = Math.min(n, a.length) - 1;
    while (lo <= hi) {
        int mid = lo + ((hi - lo) >>> 1);
        int v = a[mid];
        if (v < x) {
            lo = mid + 1;
        } else if (v > x) {
            hi = mid - 1;
        } else {
            return mid;
        }
    }
    return -1;
}
}

