class Algo {
public static int binary_search(int[] a, int n, int x) {
    java.util.function.IntBinaryOperator[] f = new java.util.function.IntBinaryOperator[1];
    f[0] = (lo, hi) -> {
        if (lo > hi) return -1;
        int mid = lo + ((hi - lo) >>> 1);
        if (a[mid] == x) return mid;
        return a[mid] < x ? f[0].applyAsInt(mid + 1, hi) : f[0].applyAsInt(lo, mid - 1);
    };
    return n <= 0 ? -1 : f[0].applyAsInt(0, n - 1);
}
}

