    while ((d & 1) == 0) { d >>= 1; s++; }
    int[] bases = {2,3,5,7,11};
    long nn = n;
    for (int a : bases) {
        if (a % n == 0) continue;
        long x = 1, b = a % nn, e = d;
        while (e > 0) {
            if ((e & 1L) != 0) x = (x * b) % nn;
            b = (b * b) % nn;
            e >>= 1;
        }
        if (x == 1 || x == nn - 1) continue;
        boolean witness = true;
        for (int r = 1; r < s; r++) {
            x = (x * x) % nn;
            if (x == nn - 1) { witness = false; break; }
        }
        if (witness) return 0;
    }
    return 1;
}
}

