class Algo {
public static int is_prime(int n) {
    if (n < 2) return 0;
    if ((n & 1) == 0) return n == 2 ? 1 : 0;
    if (n % 3 == 0) return n == 3 ? 1 : 0;
    if (n % 5 == 0) return n == 5 ? 1 : 0;
    if (n % 7 == 0) return n == 7 ? 1 : 0;
    if (n % 11 == 0) return n == 11 ? 1 : 0;
    long d = n - 1L;
    int s = 0;
    while ((d & 1L) == 0) { d >>= 1; s++; }
    int[] bases = {2, 7, 61};
    outer:
    for (int a : bases) {
        if (a >= n) continue;
        long mod = n;
        long e = d;
        long base = a % mod;
        long x = 1L;
        while (e > 0) {
            if ((e & 1L) != 0) x = (x * base) % mod;
            base = (base * base) % mod;
            e >>= 1;
        }
        if (x == 1 || x == mod - 1) continue;
        for (int r = 1; r < s; r++) {
            x = (x * x) % mod;
            if (x == mod - 1) continue outer;
            if (x == 1) return 0;
        }
        return 0;
    }
    return 1;
}
}

class Algo {
