    for (int aBase : bases) {
        long a = aBase % n;
        long x = 1L, p = a, e = d;
        while (e > 0) {
            if ((e & 1L) != 0L) x = (x * p) % n;
            p = (p * p) % n;
            e >>= 1;
        }
        if (x == 1L || x == n - 1L) continue;
        for (int r = 1; r < s; r++) {
            x = (x * x) % n;
            if (x == n - 1L) continue outer;
        }
        return 0;
    }
    return 1;
}
}

public class Algo {
