public class Algo {
    public static int lcm(int a, int b) {
        if (a == 0 || b == 0) return 0;
        long x = Math.abs((long)a);
        long y = Math.abs((long)b);
        long u = x, v = y;
        int shift = Long.numberOfTrailingZeros(u | v);
        u >>= Long.numberOfTrailingZeros(u);
        do {
            v >>= Long.numberOfTrailingZeros(v);
            if (u > v) { long t = u; u = v; v = t; }
            v -= u;
        } while (v != 0);
        long g = u << shift;
        long res = (x / g) * y;
        return (int) res;
    }
}

class Algo {
public static int lcm(int a, int b) {
    long x = Math.abs((long) a);
    long y = Math.abs((long) b);
    if (x == 0 || y == 0) return 0;
    long res = 1;
    for (long i = 2; i * i <= x || i * i <= y; i++) {
        int ea = 0;
        while (x % i == 0) { x /= i; ea++; }
        int eb = 0;
        while (y % i == 0) { y /= i; eb++; }
        int e = ea > eb ? ea : eb;
        while (e-- > 0) res *= i;
    }
    if (x > 1 && y > 1) {
        if (x == y) res *= x;
        else res *= x * y;
    } else if (x > 1) {
        res *= x;
    } else if (y > 1) {
        res *= y;
    }
    return (int) res;
}
}

