class Algo {
public static int lcm(int a, int b) {
    if (a == 0 || b == 0) return 0;
    long x = Math.abs((long) a);
    long y = Math.abs((long) b);

    long u = x, v = y;
    int tzU = Long.numberOfTrailingZeros(u);
    int tzV = Long.numberOfTrailingZeros(v);
    int shift = Math.min(tzU, tzV);

    u >>= tzU;
    v >>= tzV;

    while (u != v) {
        if (u > v) {
            long t = u;
            u = v;
            v = t;
        }
        v -= u;
        v >>= Long.numberOfTrailingZeros(v);
    }

    long g = u << shift;
    long res = (x / g) * y;
    return (int) res;
}
}

public class Algo {
    public static int lcm(int a, int b) {
        if (a == 0 || b == 0) return 0;
        long x = Math.abs((long) a);
        long y = Math.abs((long) b);
        long r = 1;
        long d = 2;
        while (x > 1 || y > 1) {
            boolean divided = false;
            if (x % d == 0) { x /= d; divided = true; }
            if (y % d == 0) { y /= d; divided = true; }
            if (divided) {
                r *= d;
            } else {
                d += (d == 2 ? 1 : 2);
            }
        }
        return (int) r;
    }
}

