class Algo {
public static long max_subarray_sum(int[] a, int n) {
    if (a == null || n <= 0) return 0L;
    int len = Math.min(n, a.length);
    if (len == 0) return 0L;
    long current = a[0];
    long best = current;
    for (int i = 1; i < len; i++) {
        long val = a[i];
        current = current < 0 ? val : current + val;
        if (current > best) best = current;
    }
    return best;
}
}

