    if (len == 0) return 0L;
    long maxSoFar = Long.MIN_VALUE;
    long curr = 0L;
    for (int i = 0; i < len; i++) {
        long ai = a[i];
        if (curr > 0) {
            curr += ai;
        } else {
            curr = ai;
        }
        if (curr > maxSoFar) {
            maxSoFar = curr;
        }
    }
    return maxSoFar;
}
}

class Algo {
public static long max_subarray_sum(int[] a, int n) {
    if (a == null || n <= 0) return 0L;
    if (n > a.length) n = a.length;
    int m = 1;
    while (m < n) m <<= 1;
    int size = m << 1;
    long[] sum = new long[size];
    long[] pref = new long[size];
    long[] suff = new long[size];
    long[] best = new long[size];
    final long NEG_INF = Long.MIN_VALUE / 4;
    for (int i = 0; i < m; i++) {
        int idx = m + i;
        if (i < n) {
            long v = a[i];
            sum[idx] = v;
            pref[idx] = v;
            suff[idx] = v;
            best[idx] = v;
        } else {
            sum[idx] = 0L;
            pref[idx] = NEG_INF;
            suff[idx] = NEG_INF;
            best[idx] = NEG_INF;
        }
    }
    for (int i = m - 1; i > 0; --i) {
        int l = i << 1, r = l + 1;
        long candPref = pref[r] == NEG_INF ? NEG_INF : sum[l] + pref[r];
        long candSuff = suff[l] == NEG_INF ? NEG_INF : sum[r] + suff[l];
        long cross = (suff[l] == NEG_INF || pref[r] == NEG_INF) ? NEG_INF : suff[l] + pref[r];
        sum[i] = sum[l] + sum[r];
        pref[i] = Math.max(pref[l], candPref);
        suff[i] = Math.max(suff[r], candSuff);
        best[i] = Math.max(Math.max(best[l], best[r]), cross);
    }
    return best[1];
}
}

public class Algo {
    public static long max_subarray_sum(int[] a, int n) {
        if (a == null || n <= 0) return 0L;
        n = Math.min(n, a.length);
        return maxSub(a, 0, n);
    }
    private static long maxSub(int[] a, int l, int r) {
        if (l + 1 == r) return a[l];
        int m = (l + r) >>> 1;
        long left = maxSub(a, l, m);
        long right = maxSub(a, m, r);
        long bestLeft = Long.MIN_VALUE, sum = 0;
        for (int i = m - 1; i >= l; i--) {
            sum += a[i];
            if (sum > bestLeft) bestLeft = sum;
        }
        long bestRight = Long.MIN_VALUE;
        sum = 0;
        for (int i = m; i < r; i++) {
            sum += a[i];
            if (sum > bestRight) bestRight = sum;
        }
        long cross = bestLeft + bestRight;
        return Math.max(Math.max(left, right), cross);
    }
}

class Algo {
public static long max_subarray_sum(int[] a, int n) {
    int end = a == null ? 0 : Math.min(n, a.length);
    if (end <= 0) return 0L;
    final java.util.function.Function<int[], long[]>[] self = new java.util.function.Function[]{null};
    self[0] = range -> {
        int l = range[0], r = range[1];
        if (l + 1 == r) {
            long v = a[l];
            return new long[]{v, v, v, v};
        }
        int m = l + ((r - l) >>> 1);
        long[] left = self[0].apply(new int[]{l, m});
        long[] right = self[0].apply(new int[]{m, r});
        long sum = left[0] + right[0];
        long maxPref = Math.max(left[1], left[0] + right[1]);
        long maxSuff = Math.max(right[2], right[0] + left[2]);
        long maxSub = Math.max(Math.max(left[3], right[3]), left[2] + right[1]);
        return new long[]{sum, maxPref, maxSuff, maxSub};
    };
    return self[0].apply(new int[]{0, end})[3];
}
}

class Algo {
public static long max_subarray_sum(final int[] a, int n) {
