class Algo {
public static long max_subarray_sum(int[] a, int n) {
    if (n <= 0) return 0L;
    if (n == 1) return (long) a[0];
    long prevBest = max_subarray_sum(a, n - 1);
    long sum = 0L;
    long bestSuffix = Long.MIN_VALUE;
    for (int i = n - 1; i >= 0; i--) {
        sum += (long) a[i];
        if (sum > bestSuffix) bestSuffix = sum;
    }
    return Math.max(prevBest, bestSuffix);
}
}

