        if (m <= 0) return 0L;
        if (m == 1) return a[0];
        int mid = m >>> 1;
        long leftBest = max_subarray_sum(java.util.Arrays.copyOfRange(a, 0, mid), mid);
        long rightBest = max_subarray_sum(java.util.Arrays.copyOfRange(a, mid, m), (long) m - mid);
        long bestCrossLeft = Long.MIN_VALUE;
        long acc = 0;
        for (int i = mid - 1; i >= 0; --i) {
            acc += a[i];
            if (acc > bestCrossLeft) bestCrossLeft = acc;
        }
        long bestCrossRight = Long.MIN_VALUE;
        acc = 0;
        for (int i = mid; i < m; ++i) {
            acc += a[i];
            if (acc > bestCrossRight) bestCrossRight = acc;
        }
        long cross = bestCrossLeft + bestCrossRight;
        return Math.max(Math.max(leftBest, rightBest), cross);
    }
}

class Algo {
