    int mid = n / 2;
    int[] left = java.util.Arrays.copyOfRange(a, 0, mid);
    int[] right = java.util.Arrays.copyOfRange(a, mid, n);
    long leftMax = max_subarray_sum(left, left.length);
    long rightMax = max_subarray_sum(right, right.length);
    long sum = 0L, leftSuffixMax = Long.MIN_VALUE;
    for (int i = left.length - 1; i >= 0; i--) {
        sum += left[i];
        if (sum > leftSuffixMax) leftSuffixMax = sum;
    }
    sum = 0L;
    long rightPrefixMax = Long.MIN_VALUE;
    for (int i = 0; i < right.length; i++) {
        sum += right[i];
        if (sum > rightPrefixMax) rightPrefixMax = sum;
    }
    long crossMax = leftSuffixMax + rightPrefixMax;
    return Math.max(Math.max(leftMax, rightMax), crossMax);
}
