class Algo {
public static long max_subarray_sum(final int[] a, long n) {
    int len = (n <= 0L) ? 0 : (n > a.length ? a.length : (int) n);
    if (len == 0) return 0L;

    int[] L = new int[64];
    int[] R = new int[64];
    int[] ST = new int[64];
    int sp = 0;

    long[] best = new long[64];
    long[] pref = new long[64];
    long[] suff = new long[64];
    long[] sum = new long[64];
    int rsp = 0;

    L[sp] = 0; R[sp] = len; ST[sp] = 0; sp++;

    while (sp > 0) {
        int l = L[--sp], r = R[sp], st = ST[sp];
        int width = r - l;
        if (width <= 1) {
            if (rsp >= best.length) {
                int nc = best.length << 1;
                best = java.util.Arrays.copyOf(best, nc);
                pref = java.util.Arrays.copyOf(pref, nc);
                suff = java.util.Arrays.copyOf(suff, nc);
                sum = java.util.Arrays.copyOf(sum, nc);
            }
            long v = (long) a[l];
            best[rsp] = v;
            pref[rsp] = v;
            suff[rsp] = v;
            sum[rsp] = v;
            rsp++;
        } else if (st == 0) {
            if (sp + 2 >= L.length) {
                int nc = L.length << 1;
                L = java.util.Arrays.copyOf(L, nc);
                R = java.util.Arrays.copyOf(R, nc);
                ST = java.util.Arrays.copyOf(ST, nc);
            }
            int m = (l + r) >>> 1;
            L[sp] = l; R[sp] = r; ST[sp] = 1; sp++;
            L[sp] = m; R[sp] = r; ST[sp] = 0; sp++;
            L[sp] = l; R[sp] = m; ST[sp] = 0; sp++;
        } else {
            long rbest = best[--rsp], rpref = pref[rsp], rsuff = suff[rsp], rsum = sum[rsp];
            long lbest = best[--rsp], lpref = pref[rsp], lsuff = suff[rsp], lsum = sum[rsp];
            long s = lsum + rsum;
            long p = Math.max(lpref, lsum + rpref);
            long t = Math.max(rsuff, rsum + lsuff);
            long b = Math.max(Math.max(lbest, rbest), lsuff + rpref);
            if (rsp >= best.length) {
                int nc = best.length << 1;
                best = java.util.Arrays.copyOf(best, nc);
                pref = java.util.Arrays.copyOf(pref, nc);
                suff = java.util.Arrays.copyOf(suff, nc);
                sum = java.util.Arrays.copyOf(sum, nc);
            }
            best[rsp] = b;
            pref[rsp] = p;
            suff[rsp] = t;
            sum[rsp] = s;
            rsp++;
        }
    }
    return best[rsp - 1];
}
}

