        sum[i] = sum[l] + sum[r];
        long prefCand1 = pref[l];
        long prefCand2 = (pref[r] == NEG_INF) ? NEG_INF : sum[l] + pref[r];
        pref[i] = Math.max(prefCand1, prefCand2);
        long suffCand1 = suff[r];
        long suffCand2 = (suff[l] == NEG_INF) ? NEG_INF : sum[r] + suff[l];
        suff[i] = Math.max(suffCand1, suffCand2);
        long bestCand = best[l] >= best[r] ? best[l] : best[r];
        long crossCand = (suff[l] == NEG_INF || pref[r] == NEG_INF) ? NEG_INF : suff[l] + pref[r];
        best[i] = bestCand >= crossCand ? bestCand : crossCand;
    }
    return best[1];
}
}

class Algo {
public static long max_subarray_sum(int[] a, int n) {
    if (a == null || n <= 0) return 0L;
    int len = Math.min(n, a.length);
    long maxSoFar = Long.MIN_VALUE;
    long maxEndingHere = 0L;
    for (int i = 0; i < len; i++) {
        long v = a[i];
        if (maxEndingHere <= 0) {
            maxEndingHere = v;
        } else {
            maxEndingHere += v;
        }
        if (maxEndingHere > maxSoFar) {
            maxSoFar = maxEndingHere;
        }
    }
    return maxSoFar == Long.MIN_VALUE ? 0L : maxSoFar;
}
}

class Algo {
public static long max_subarray_sum(int[] a, int n) {
    if (a == null || n <= 0) return 0L;
    int len = Math.min(n, a.length);
    if (len == 0) return 0L;
    long maxEndingHere = a[0];
    long maxSoFar = maxEndingHere;
    for (int i = 1; i < len; i++) {
        long x = a[i];
        if (maxEndingHere < 0) maxEndingHere = x;
        else maxEndingHere += x;
        if (maxEndingHere > maxSoFar) maxSoFar = maxEndingHere;
    }
    return maxSoFar;
}
}

class Algo {
public static long max_subarray_sum(final int[] a, final int n) {
    if (n <= 0) return 0L;
    long sum = 0L;
    long minPrefix = 0L;
    long best = Long.MIN_VALUE;
    for (int i = 0; i < n; i++) {
        sum += (long) a[i];
        long candidate = sum - minPrefix;
        if (candidate > best) best = candidate;
        if (sum < minPrefix) minPrefix = sum;
    }
    return best;
}
}

