class Algo {
public static void reverse_array(int[] a, int n) {
    if (n <= 1) return;
    final int limit = n >> 1;
    final java.util.function.IntConsumer[] rec = new java.util.function.IntConsumer[1];
    rec[0] = i -> {
        if (i >= limit) return;
        int j = n - 1 - i;
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
        rec[0].accept(i + 1);
    };
    rec[0].accept(0);
}
}

class Algo {
public static void reverse_array(int[] a, int n) {
