    boolean[] visited = new boolean[len];
    for (int i = 0; i < len; i++) {
        if (visited[i]) continue;
        int j = len - 1 - i;
        if (j == i) {
            visited[i] = true;
        } else {
            int tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
            visited[i] = true;
            visited[j] = true;
        }
    }
}
}

