public class Algo {
    public static long sum_array(int[] a, int n) {
        if (a == null || n <= 0) return 0L;
        int m = n > a.length ? a.length : n;
        long sum = 0L;
        int[] ls = new int[64];
        int[] rs = new int[64];
        int sp = 0;
        ls[sp] = 0;
        rs[sp] = m;
        sp++;
        while (sp > 0) {
            sp--;
            int lo = ls[sp];
            int hi = rs[sp];
            int len = hi - lo;
            if (len <= 0) continue;
            if (len == 1) {
                sum += a[lo];
            } else {
                int mid = lo + (len >>> 1);
                ls[sp] = lo;
                rs[sp] = mid;
                sp++;
                ls[sp] = mid;
                rs[sp] = hi;
                sp++;
            }
        }
        return sum;
    }
}

