class Algo {
public static long sum_array(int[] a, long n) {
    if (a == null || n <= 0) return 0L;
    int m = (int) Math.min((long) a.length, Math.min(n, (long) Integer.MAX_VALUE));
    if (m <= 0) return 0L;
    long sum = 0L;
    final int THRESH = 2048;
    if (m <= THRESH) {
        for (int i = 0; i < m; i++) sum += a[i];
        return sum;
    }
    int[] sL = new int[64];
    int[] sR = new int[64];
    int sp = 0;
    int l = 0, r = m;
    while (true) {
        int len = r - l;
        if (len <= THRESH) {
            long local = 0L;
            for (int i = l; i < r; i++) local += a[i];
            sum += local;
            if (sp == 0) break;
            --sp;
            l = sL[sp];
            r = sR[sp];
        } else {
            int mid = l + (len >>> 1);
            sL[sp] = mid;
            sR[sp] = r;
            sp++;
            r = mid;
        }
    }
    return sum;
}
}

