public static long sum_array(int[] a, int n) {
    if (n <= 0) return 0L;
    long[] buf = new long[n];
    for (int i = 0; i < n; i++) buf[i] = a[i];
    int m = n;
    while (m > 1) {
        int k = 0, i = 0;
        for (; i + 1 < m; i += 2) buf[k++] = buf[i] + buf[i + 1];
        if (i < m) buf[k++] = buf[i];
        m = k;
    }
    return buf[0];
}
}

